const allModules=['Dashboard','Approvals','POS','Orders','Products','Inventory','Customers','Suppliers','Purchasing','Expenses','Cash Drawer','Reports','Staff','Branches','Restaurant','Pharmacy','Production','Payroll & HR','Route Sales','Audit Logs','Settings','SaaS Admin'];
const mapName={purchasing:'Purchasing',restaurant:'Restaurant',pharmacy:'Pharmacy',payroll:'Payroll & HR',production:'Production',route_sales:'Route Sales',reports:'Reports',pos:'POS',products:'Products',customers:'Customers',expenses:'Expenses'};
let token=localStorage.getItem('pos_token')||'',user=null,cart=[],enabledModules=[];
const $=id=>document.getElementById(id),money=v=>'UGX '+Number(v||0).toLocaleString(),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function api(path,opts={}){const r=await fetch('/api'+path,{...opts,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token,...(opts.headers||{})}});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Request failed');return j}
function showRegister(){$('loginPane').classList.add('hidden');$('registerPane').classList.remove('hidden')}function showLogin(){$('registerPane').classList.add('hidden');$('loginPane').classList.remove('hidden')}
async function register(){try{const j=await api('/register',{method:'POST',body:JSON.stringify({name:$('rname').value,businessName:$('rbiz').value,email:$('remail').value,password:$('rpass').value,country:$('rcountry').value,currency:$('rcountry').value==='Uganda'?'UGX':$('rcountry').value==='Kenya'?'KES':$('rcountry').value==='Ghana'?'GHS':$('rcountry').value==='Nigeria'?'NGN':'RWF'})});token=j.token;user={...j.user,businessId:j.business.id};localStorage.setItem('pos_token',token);showApp()}catch(e){$('registerMsg').textContent=e.message;$('registerMsg').className='bad'}}
async function login(){try{const j=await api('/login',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('password').value})});token=j.token;user=j.user;localStorage.setItem('pos_token',token);showApp()}catch(e){$('loginMsg').textContent=e.message;$('loginMsg').className='bad'}}
function logout(){localStorage.removeItem('pos_token');location.reload()}
async function showApp(){$('login').classList.add('hidden');$('app').classList.remove('hidden');if(!user)user=await api('/me');$('who').textContent=(user?.name||'User')+' · '+(user?.role||'');await loadModules();renderNav();openModule(user.role==='saas_admin'?'SaaS Admin':'Dashboard')}
async function loadModules(){if(user.role==='saas_admin'){enabledModules=allModules;return}const rows=await api('/modules');enabledModules=['Dashboard','Approvals','Orders','Inventory','Suppliers','Cash Drawer','Staff','Branches','Audit Logs','Settings'];rows.filter(x=>x.enabled&&x.active&&(x.core||!x.expires_at||new Date(x.expires_at)>new Date())).forEach(x=>{const n=mapName[x.code];if(n&&!enabledModules.includes(n))enabledModules.push(n)})}
function renderNav(){if(user.role==='saas_admin'){$('nav').innerHTML='<div class="nav-section">Platform Administration</div>'+['SaaS Admin'].map(m=>'<button data-m="'+m+'" onclick="openModule(\''+m+'\')">'+m+'</button>').join('');return}const allowed=m=>enabledModules.includes(m);const ops=['Dashboard','POS','Orders','Restaurant','Customers'].filter(allowed),admin=['Approvals','Products','Inventory','Suppliers','Purchasing','Expenses','Cash Drawer','Reports','Staff','Branches','Audit Logs','Settings'].filter(allowed);$('nav').innerHTML='<div class="nav-section">Restaurant Operations</div>'+ops.map(m=>'<button data-m="'+m+'" onclick="openModule(\''+m+'\')">'+m+'</button>').join('')+'<div class="nav-section admin-section">Administration</div>'+admin.map(m=>'<button data-m="'+m+'" onclick="openModule(\''+m+'\')">'+m+'</button>').join('')}
function setActive(m){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.m===m));$('title').textContent=m}
function card(label,value,sub='',tone=''){return `<div class="kpi ${tone}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`}

function bindPdfLinks(){document.querySelectorAll('[data-pdf]').forEach(btn=>btn.addEventListener('click',()=>openPdf(btn.dataset.pdf).catch(e=>alert(e.message))))}
async function openPdf(path){const r=await fetch('/api'+path,{headers:{'Authorization':'Bearer '+token}});if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||'Unable to generate PDF')}const blob=await r.blob(),url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),120000)}
async function getDocSettings(){return api('/document-settings')}
function previewDocument(title,number,meta,lines,total,currency='UGX'){const w=window.open('','_blank','width=900,height=900');const rows=lines.map(x=>'<tr><td>'+esc(x.name)+'</td><td class="right">'+esc(x.qty??'')+'</td><td class="right">'+esc(x.unit??'')+'</td><td class="right">'+esc(x.total??'')+'</td></tr>').join('');w.document.write('<!doctype html><html><head><title>'+esc(title)+'</title><style>body{font-family:Arial,sans-serif;margin:36px;color:#111}.head{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:14px;margin-bottom:20px}.head h1{margin:0;font-size:20px}.doc{text-align:right}.meta{display:grid;gap:5px;margin:18px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.total{text-align:right;font-size:20px;font-weight:700;margin-top:20px}.note{margin-top:26px;color:#666;font-size:12px}@media print{button{display:none}}</style></head><body><div class="head"><div><h1>DOCUMENT PREVIEW</h1><div>Unsaved preview</div></div><div class="doc"><b>'+esc(title)+'</b><div>'+esc(number||'Draft')+'</div></div></div><div class="meta">'+Object.entries(meta||{}).map(([k,v])=>'<div><b>'+esc(k)+':</b> '+esc(v)+'</div>').join('')+'</div><table><thead><tr><th>Item / Description</th><th class="right">Qty</th><th class="right">Unit</th><th class="right">Total</th></tr></thead><tbody>'+rows+'</tbody></table><div class="total">'+esc(currency)+' '+Number(total||0).toLocaleString()+'</div><div class="note">Preview only — this document has not been saved or posted.</div><button onclick="window.print()">Print Preview</button></body></html>');w.document.close()}

async function loadDashboard(){setActive('Dashboard');const d=await api('/dashboard');const trial=d.business?.trial_ends_at?Math.max(0,Math.ceil((new Date(d.business.trial_ends_at)-Date.now())/86400000)):null;$('view').innerHTML=`<div class="panel banner"><div><b>${esc(d.business?.name||'Business')}</b><span>${esc(d.business?.status||'active')}${trial!==null?' · '+trial+' trial days left':''}</span></div><button class="secondary" onclick="openModule('Settings')">Manage plan</button></div><div class="kpi-grid">${card('Revenue Today',money(d.revenueToday),'Across all payments','green')}${card('Gross Profit',money(d.grossProfitToday),'From product cost','blue')}${card('Sales Today',d.salesToday,'Completed receipts','purple')}${card('Expenses Today',money(d.expensesToday),'Operating costs','orange')}${card('Low Stock',d.lowStock,'Needs attention',d.lowStock?'red':'')}${card('Month Revenue',money(d.revenueMonth),'Current month')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Recent sales</h3></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Cashier</th><th>Payment</th><th class="right">Total</th></tr></thead><tbody>${d.recentSales.map(x=>`<tr><td>${esc(x.receipt_no)}</td><td>${esc(x.cashier)}</td><td><span class="pill">${esc(x.payment_method)}</span></td><td class="right">${money(x.total)}</td></tr>`).join('')||'<tr><td colspan=4>No sales yet</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Best sellers · 30 days</h3>${d.bestSellers.map(x=>`<div class="rank"><div><b>${esc(x.product_name)}</b><small>${Number(x.qty)} units</small></div><strong>${money(x.total)}</strong></div>`).join('')||'<div class="empty">No sales yet</div>'}</div></div>`}
async function openModule(m){setActive(m);if(m==='Dashboard')return loadDashboard();if(m==='SaaS Admin')return saas();if(!enabledModules.includes(m)&&user.role!=='saas_admin'){return $('view').innerHTML='<div class="panel"><h3>Add-on not enabled</h3><p class="muted">Ask your SaaS administrator to enable this module for your tenant.</p></div>'}if(m==='POS')return pos();if(m==='Orders')return orders();if(m==='Products')return products(m);if(m==='Inventory')return inventory();if(m==='Customers')return people('customers','Customer');if(m==='Approvals')return approvals();if(m==='Suppliers')return suppliers();if(m==='Purchasing')return purchasing();if(m==='Expenses')return expenses();if(m==='Cash Drawer')return cash();if(m==='Settings')return settings();$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>${m}</h3><span class="pill">Enabled</span></div><p class="muted">This add-on is enabled for this tenant. Deeper workflow screens are being added.</p></div>`}
async function saas(){if(user.role!=='saas_admin')return;const tenants=await api('/saas/tenants');$('view').innerHTML=`<div class="kpi-grid">${card('Tenants',tenants.length,'Registered businesses','blue')}${card('Trials',tenants.filter(x=>x.status==='trial').length,'Active trials','purple')}${card('Active',tenants.filter(x=>x.status==='active').length,'Paid/active','green')}</div><div class="panel"><div class="panel-head"><h3>Tenant control</h3><span class="muted">Turn modules on/off and override prices per tenant</span></div><div class="table-wrap"><table><thead><tr><th>Business</th><th>Country</th><th>Status</th><th>Trial ends</th><th>Users</th><th></th></tr></thead><tbody>${tenants.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.country)}</td><td><span class="pill">${esc(t.status)}</span></td><td>${t.trial_ends_at?new Date(t.trial_ends_at).toLocaleDateString():'—'}</td><td>${t.users}</td><td class="right"><button class="secondary" onclick="tenantModules(${t.id},'${esc(t.name).replace(/'/g,"&#39;")}')">Modules</button></td></tr>`).join('')}</tbody></table></div></div><div id="tenantModules"></div>`}
async function tenantModules(id,name){const rows=await api('/saas/tenants/'+id+'/modules');$('tenantModules').innerHTML=`<div class="panel"><div class="panel-head"><h3>${esc(name)} · Add-ons</h3></div><div class="modules">${rows.map(x=>`<div class="module"><h3>${esc(x.name)}</h3><p class="muted">${esc(x.description||'')}</p><div class="price">${money(x.price_override??x.monthly_price)}/mo</div><label><input type="checkbox" ${x.enabled?'checked':''} onchange="toggleModule(${id},'${x.code}',this.checked,${Number(x.price_override??x.monthly_price)})"> Enabled</label><input id="price-${id}-${x.code}" type="number" value="${Number(x.price_override??x.monthly_price)}" placeholder="Monthly price"><button class="secondary" onclick="saveModulePrice(${id},'${x.code}',${x.enabled?'true':'false'})">Save price</button></div>`).join('')}</div></div>`}
async function toggleModule(id,code,enabled,price){await api('/saas/tenants/'+id+'/modules/'+code,{method:'PUT',body:JSON.stringify({enabled,priceOverride:price,trial:false})})}
async function saveModulePrice(id,code,enabled){await api('/saas/tenants/'+id+'/modules/'+code,{method:'PUT',body:JSON.stringify({enabled,priceOverride:Number($('price-'+id+'-'+code).value),trial:false})});alert('Module price updated')}
async function products(label='Products'){const ps=await api('/products');$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>${label}</h3><button onclick="productForm()">+ Add product</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>SKU</th><th>Barcode</th><th>Suppliers</th><th class="right">Price</th><th class="right">Stock</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.category)}</td><td>${esc(p.sku||'-')}</td><td>${esc(p.barcode||'-')}</td><td>${(p.suppliers||[]).map(s=>`<span class="pill">${esc(s.name)}</span>`).join(' ')||'<span class="muted">None assigned</span>'}</td><td class="right">${money(p.price)}</td><td class="right">${p.stock}</td><td class="right"><button class="secondary" onclick="manageProductSuppliers(${p.id},'${esc(p.name).replace(/'/g,"&#39;")}')">Suppliers</button></td></tr>`).join('')}</tbody></table></div></div>`}
async function productForm(){const sups=await api('/suppliers');$('form').innerHTML=`<div class="inline-form"><input id="pn" placeholder="Product name"><input id="psku" placeholder="SKU"><input id="pbar" placeholder="Barcode"><input id="pcat" placeholder="Category"><input id="pcost" type="number" min="0" placeholder="Cost"><input id="pprice" type="number" min="0" placeholder="Price"><input id="pstock" type="number" min="0" placeholder="Opening stock"><div class="selection-box"><b>Supplied by</b><small>Select all suppliers that can supply this product.</small><div class="check-grid">${sups.map(s=>`<label><input type="checkbox" data-product-supplier="${s.id}"> ${esc(s.name)}</label>`).join('')||'<span class="muted">No suppliers registered yet.</span>'}</div></div><button onclick="saveProduct()">Save product</button></div>`}
async function saveProduct(){const supplierIds=[...document.querySelectorAll('[data-product-supplier]:checked')].map(x=>Number(x.dataset.productSupplier));await api('/products',{method:'POST',body:JSON.stringify({name:$('pn').value,sku:$('psku').value,barcode:$('pbar').value,category:$('pcat').value,cost:$('pcost').value,price:$('pprice').value,stock:$('pstock').value,supplierIds})});products('Products')}
async function manageProductSuppliers(id,name){const [sups,ps]=await Promise.all([api('/suppliers'),api('/products')]),p=ps.find(x=>Number(x.id)===Number(id)),chosen=new Set((p?.suppliers||[]).map(x=>Number(x.id)));$('form').innerHTML=`<div class="relation-editor"><div><h4>${esc(name)} - Suppliers</h4><p class="muted">Choose every supplier allowed to supply this product.</p></div><div class="check-grid">${sups.map(s=>`<label><input type="checkbox" data-edit-product-supplier="${s.id}" ${chosen.has(Number(s.id))?'checked':''}> ${esc(s.name)}</label>`).join('')||'<span class="muted">No suppliers registered.</span>'}</div><button onclick="saveProductSuppliers(${id})">Save supplier list</button></div>`}
async function saveProductSuppliers(id){const supplierIds=[...document.querySelectorAll('[data-edit-product-supplier]:checked')].map(x=>Number(x.dataset.editProductSupplier));await api('/products/'+id+'/suppliers',{method:'PUT',body:JSON.stringify({supplierIds})});products('Products')}

async function inventory(){const [o,locs,bals,transfers,counts,moves,branches]=await Promise.all([api('/inventory/overview'),api('/inventory/locations'),api('/inventory/balances'),api('/inventory/transfers'),api('/inventory/counts'),api('/stock-movements'),api('/branches')]);const locRows=locs.map(l=>'<tr><td><b>'+esc(l.name)+'</b><small>'+esc(l.location_type)+'</small></td><td>'+esc(l.branch_name)+'</td><td>'+Number(l.total_units)+'</td><td>'+money(l.stock_value)+'</td><td>'+(l.is_default?'<span class="pill">Default</span>':'')+'</td></tr>').join('')||'<tr><td colspan="5">No stock locations.</td></tr>';const balRows=bals.map(x=>'<tr><td><b>'+esc(x.product_name)+'</b><small>'+esc(x.sku||'')+'</small></td><td>'+esc(x.branch_name)+'</td><td>'+esc(x.location_name)+'</td><td>'+Number(x.qty)+'</td><td>'+money(x.avg_cost)+'</td><td>'+money(Number(x.qty)*Number(x.avg_cost))+'</td></tr>').join('')||'<tr><td colspan="6">No location balances yet.</td></tr>';const transferRows=transfers.slice(0,10).map(x=>'<tr><td><b>'+esc(x.reference_no)+'</b></td><td>'+esc(x.from_location)+'</td><td>'+esc(x.to_location)+'</td><td>'+Number(x.total_qty)+'</td><td>'+new Date(x.created_at).toLocaleString()+'</td></tr>').join('')||'<tr><td colspan="5">No transfers yet.</td></tr>';const countRows=counts.slice(0,10).map(x=>'<tr><td><b>'+esc(x.reference_no)+'</b></td><td>'+esc(x.location_name)+'</td><td><span class="pill">'+esc(x.status)+'</span></td><td>'+new Date(x.created_at).toLocaleString()+'</td><td class="right">'+(x.status==='draft'?'<button onclick="openStockCount('+x.id+')">Count stock</button>':'')+'</td></tr>').join('')||'<tr><td colspan="5">No stock counts yet.</td></tr>';const moveRows=moves.slice(0,20).map(x=>'<tr><td>'+new Date(x.created_at).toLocaleString()+'</td><td><b>'+esc(x.product_name)+'</b></td><td>'+esc(x.branch_name||'')+'</td><td><span class="pill">'+esc(x.movement_type)+'</span></td><td>'+Number(x.quantity)+'</td><td>'+esc(x.reference_no||'-')+'</td></tr>').join('')||'<tr><td colspan="6">No stock movements.</td></tr>';$('view').innerHTML='<div class="kpi-grid purchase-kpis">'+card('Locations',o.locations,'Active stock locations','blue')+card('Stock Value',money(o.stockValue),'Across all locations','green')+card('Low Stock',o.lowStock,'At or below reorder level',o.lowStock?'red':'')+card('Open Counts',o.openCounts,'Draft physical counts','purple')+'</div><div class="panel"><div class="panel-head"><div><h3>Inventory Control</h3><p class="muted">Location-based stock, transfers, adjustments, wastage and physical counts.</p></div><div class="action-row"><button class="secondary" onclick="newInventoryLocation()">+ Location</button><button class="secondary" onclick="newStockAdjustment()">Adjustment</button><button class="secondary" onclick="newStockTransfer()">Transfer</button><button onclick="newStockCount()">Stock Count</button></div></div><div id="inventoryWork"></div></div><div class="two-col"><div class="panel"><h3>Stock Locations</h3><div class="table-wrap"><table><thead><tr><th>Location</th><th>Branch</th><th>Units</th><th>Value</th><th></th></tr></thead><tbody>'+locRows+'</tbody></table></div></div><div class="panel"><h3>Recent Transfers</h3><div class="table-wrap"><table><thead><tr><th>Reference</th><th>From</th><th>To</th><th>Qty</th><th>Date</th></tr></thead><tbody>'+transferRows+'</tbody></table></div></div></div><div class="panel"><h3>Location Balances</h3><div class="table-wrap"><table><thead><tr><th>Product</th><th>Branch</th><th>Location</th><th>Qty</th><th>Avg Cost</th><th>Value</th></tr></thead><tbody>'+balRows+'</tbody></table></div></div><div class="two-col"><div class="panel"><h3>Physical Stock Counts</h3><div class="table-wrap"><table><thead><tr><th>Count</th><th>Location</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody>'+countRows+'</tbody></table></div></div><div class="panel"><h3>Recent Stock Movements</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Branch</th><th>Type</th><th>Qty</th><th>Reference</th></tr></thead><tbody>'+moveRows+'</tbody></table></div></div></div>';window._inventoryLocations=locs;window._inventoryBranches=branches;window._inventoryBalances=bals}
async function newInventoryLocation(){const branches=window._inventoryBranches||await api('/branches');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>New Stock Location</h4><div class="form-row"><label>Branch<select id="invBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Location name<input id="invLocName" placeholder="e.g. Kitchen Store"></label><label>Type<select id="invLocType"><option value="store">Store</option><option value="kitchen">Kitchen</option><option value="bar">Bar</option><option value="cold_room">Cold Room</option><option value="freezer">Freezer</option><option value="packaging">Packaging</option></select></label></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="saveInventoryLocation()">Save Location</button></div></div>'}
async function saveInventoryLocation(){await api('/inventory/locations',{method:'POST',body:JSON.stringify({branchId:Number($('invBranch').value),name:$('invLocName').value,locationType:$('invLocType').value})});inventory()}
async function newStockAdjustment(){const [locs,products]=await Promise.all([api('/inventory/locations'),api('/products')]);$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>Stock Adjustment / Wastage</h4><div class="form-row"><label>Location<select id="adjLocation">'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>Type<select id="adjType"><option value="adjustment">Adjustment</option><option value="wastage">Wastage</option><option value="spoilage">Spoilage</option></select></label><label>Reason<input id="adjReason" placeholder="Reason"></label></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity change</th><th>Unit cost</th><th></th></tr></thead><tbody id="adjLines"></tbody></table></div><div class="form-row"><label>Add product<select id="adjProduct"><option value="">Choose product</option>'+products.map(p=>'<option value="'+p.id+'" data-cost="'+Number(p.cost)+'">'+esc(p.name)+'</option>').join('')+'</select></label><button onclick="addAdjustmentLine()" type="button">Add Item</button></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="postAdjustment()">Post Adjustment</button></div></div>';window._adjItems=[]}
function addAdjustmentLine(){const sel=$('adjProduct'),pid=Number(sel.value);if(!pid)return;const opt=sel.options[sel.selectedIndex],name=opt.text,cost=Number(opt.dataset.cost||0);if(!window._adjItems.find(x=>x.productId===pid))window._adjItems.push({productId:pid,name,qtyChange:-1,unitCost:cost});renderAdjustmentLines()}
function renderAdjustmentLines(){const body=$('adjLines');if(!body)return;body.innerHTML=window._adjItems.map((x,i)=>'<tr><td><b>'+esc(x.name)+'</b></td><td><input class="mini-input" type="number" step="0.001" value="'+x.qtyChange+'" onchange="_adjItems['+i+'].qtyChange=Number(this.value)"></td><td><input class="mini-input" type="number" min="0" value="'+x.unitCost+'" onchange="_adjItems['+i+'].unitCost=Number(this.value)"></td><td><button class="ghost" onclick="_adjItems.splice('+i+',1);renderAdjustmentLines()">Remove</button></td></tr>').join('')}
async function postAdjustment(){if(!window._adjItems?.length)return alert('Add at least one product');const r=await api('/inventory/adjustments',{method:'POST',body:JSON.stringify({locationId:Number($('adjLocation').value),adjustmentType:$('adjType').value,reason:$('adjReason').value,items:window._adjItems})});if(r.pendingApproval)alert('Submitted for management approval. Stock will change only after approval.');inventory()}
async function newStockTransfer(){const locs=await api('/inventory/locations');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>Stock Transfer</h4><div class="form-row"><label>From<select id="trFrom" onchange="loadTransferProducts()"><option value="">Choose source</option>'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>To<select id="trTo"><option value="">Choose destination</option>'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>Notes<input id="trNotes" placeholder="Optional notes"></label></div><div id="trProducts"></div><div id="trLines"></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="postTransfer()">Post Transfer</button></div></div>';window._transferItems=[];window._transferProducts=[]}
async function loadTransferProducts(){const lid=Number($('trFrom').value);window._transferItems=[];renderTransferLines();if(!lid){$('trProducts').innerHTML='';return}const bals=await api('/inventory/balances?locationId='+lid);window._transferProducts=bals.filter(x=>Number(x.qty)>0);$('trProducts').innerHTML='<div class="product-grid">'+(window._transferProducts.map(p=>'<button class="product-tile" data-tr-product="'+p.product_id+'"><b>'+esc(p.product_name)+'</b><span>'+Number(p.qty)+' available</span><small>'+esc(p.sku||'')+'</small></button>').join('')||'<div class="empty">No stock available at this location.</div>')+'</div>';document.querySelectorAll('[data-tr-product]').forEach(btn=>btn.addEventListener('click',()=>addTransferLine(Number(btn.dataset.trProduct))))}
function addTransferLine(pid){const p=window._transferProducts.find(x=>Number(x.product_id)===pid);if(!p)return;const x=window._transferItems.find(i=>i.productId===pid);if(x){if(x.qty<Number(p.qty))x.qty++}else window._transferItems.push({productId:pid,name:p.product_name,qty:1,max:Number(p.qty)});renderTransferLines()}
function renderTransferLines(){if(!$('trLines'))return;$('trLines').innerHTML=window._transferItems.length?'<div class="table-wrap"><table><thead><tr><th>Product</th><th>Available</th><th>Transfer Qty</th><th></th></tr></thead><tbody>'+window._transferItems.map((x,i)=>'<tr><td><b>'+esc(x.name)+'</b></td><td>'+x.max+'</td><td><input class="mini-input" type="number" min="0.001" max="'+x.max+'" step="0.001" value="'+x.qty+'" onchange="_transferItems['+i+'].qty=Number(this.value)"></td><td><button class="ghost" onclick="_transferItems.splice('+i+',1);renderTransferLines()">Remove</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Choose a source location and add products.</div>'}
async function postTransfer(){if(!$('trFrom').value||!$('trTo').value)return alert('Choose source and destination');if(Number($('trFrom').value)===Number($('trTo').value))return alert('Source and destination must be different');if(!window._transferItems?.length)return alert('Add products to transfer');await api('/inventory/transfers',{method:'POST',body:JSON.stringify({fromLocationId:Number($('trFrom').value),toLocationId:Number($('trTo').value),notes:$('trNotes').value,items:window._transferItems.map(x=>({productId:x.productId,qty:x.qty}))})});inventory()}
async function newStockCount(){const locs=await api('/inventory/locations');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>Start Physical Stock Count</h4><div class="form-row"><label>Location<select id="countLocation">'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>Notes<input id="countNotes" placeholder="Optional notes"></label></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="createStockCount()">Start Count</button></div></div>'}
async function createStockCount(){const c=await api('/inventory/counts',{method:'POST',body:JSON.stringify({locationId:Number($('countLocation').value),notes:$('countNotes').value})});openStockCount(c.id)}
async function openStockCount(id){const d=await api('/inventory/counts/'+id);const rows=d.items.map(x=>'<tr><td><b>'+esc(x.product_name)+'</b><small>'+esc(x.sku||'')+'</small></td><td>'+Number(x.expected_qty)+'</td><td><input class="mini-input count-value" data-item="'+x.id+'" data-expected="'+Number(x.expected_qty)+'" type="number" min="0" step="0.001" value="'+(x.counted_qty??x.expected_qty)+'"></td><td class="variance">'+(Number(x.counted_qty??x.expected_qty)-Number(x.expected_qty)).toFixed(3)+'</td></tr>').join('');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>'+esc(d.count.reference_no)+' · '+esc(d.count.location_name)+'</h4><p class="muted">Enter the physical quantity actually counted for every product.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Expected</th><th>Counted</th><th>Variance</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Save for later</button><button onclick="postStockCount('+id+')">Post Count & Adjust Stock</button></div></div>';document.querySelectorAll('.count-value').forEach(inp=>inp.addEventListener('input',()=>{const variance=Number(inp.value)-Number(inp.dataset.expected);inp.closest('tr').querySelector('.variance').textContent=variance.toFixed(3)}))}
async function postStockCount(id){const items=[...document.querySelectorAll('.count-value')].map(x=>({itemId:Number(x.dataset.item),countedQty:Number(x.value)}));await api('/inventory/counts/'+id+'/post',{method:'POST',body:JSON.stringify({items})});inventory()}

async function approvals(){const [pending,rules,staff]=await Promise.all([api('/approvals?status=pending'),api('/approval-rules'),api('/staff')]);const pendingRows=pending.map(a=>'<tr><td><b>'+esc(a.reference_no||('#'+a.id))+'</b><small>'+new Date(a.requested_at).toLocaleString()+'</small></td><td>'+esc(a.section)+'</td><td>'+esc(a.title)+'</td><td>'+esc(a.requested_by_name||'')+'</td><td class="right">'+(a.amount!=null?money(a.amount):'-')+'</td><td>'+esc(a.request_comment||'-')+'</td><td class="right"><button class="secondary" data-reject-approval="'+a.id+'">Reject</button> <button data-approve-approval="'+a.id+'">Approve</button></td></tr>').join('')||'<tr><td colspan="7"><div class="empty">No approvals waiting for you.</div></td></tr>';const actionNames={purchase_order:'Purchase Orders',inventory_wastage:'Wastage',inventory_spoilage:'Spoilage'};const ruleCards=rules.map(r=>'<div class="approval-rule"><div><b>'+esc(actionNames[r.action_type]||r.action_type)+'</b><small>'+esc(r.section)+'</small></div><select id="approver-'+r.action_type+'"><option value="">By role: '+esc(r.approver_role||'owner')+'</option>'+staff.map(s=>'<option value="'+s.id+'" '+(String(s.id)===String(r.approver_user_id||'')?'selected':'')+'>'+esc(s.name)+' · '+esc(s.role)+'</option>').join('')+'</select><button class="secondary approval-rule-save" data-action="'+esc(r.action_type)+'" data-section="'+esc(r.section)+'">Assign Supervisor</button></div>').join('');$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Approval Center</h3><p class="muted">Sensitive transactions execute only after the responsible supervisor or management approves them.</p></div><span class="pill">'+pending.length+' pending</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Section</th><th>Request</th><th>Requested By</th><th class="right">Amount</th><th>Request Comment</th><th></th></tr></thead><tbody>'+pendingRows+'</tbody></table></div></div><div class="panel"><div class="panel-head"><div><h3>Approval Routing</h3><p class="muted">Assign the respective supervisor for each controlled action. Owners/admins keep management override authority.</p></div></div><div class="approval-rules">'+ruleCards+'</div></div>';document.querySelectorAll('[data-approve-approval]').forEach(b=>b.addEventListener('click',()=>approveApproval(Number(b.dataset.approveApproval))));document.querySelectorAll('[data-reject-approval]').forEach(b=>b.addEventListener('click',()=>rejectApproval(Number(b.dataset.rejectApproval))));document.querySelectorAll('.approval-rule-save').forEach(b=>b.addEventListener('click',()=>saveApprovalRule(b.dataset.action,b.dataset.section)))}
async function approveApproval(id){const comment=prompt('Approval comment (optional):')||'';if(!confirm('Approve this request? The controlled transaction will be executed.'))return;await api('/approvals/'+id+'/approve',{method:'POST',body:JSON.stringify({comment})});approvals()}
async function rejectApproval(id){const comment=prompt('Reason for rejection (required):');if(!comment||!comment.trim())return alert('A rejection comment is required');await api('/approvals/'+id+'/reject',{method:'POST',body:JSON.stringify({comment:comment.trim()})});approvals()}
async function saveApprovalRule(actionType,section){const v=$('approver-'+actionType).value;await api('/approval-rules/'+actionType,{method:'PUT',body:JSON.stringify({section,approverUserId:v?Number(v):null,approverRole:v?null:'owner'})});alert('Approval supervisor updated');approvals()}

async function suppliers(){const rows=await api('/suppliers');$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>Suppliers</h3><button onclick="supplierForm()">+ Add supplier</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Phone</th><th>Email</th><th>Products supplied</th><th class="right">Balance</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.phone||'-')}</td><td>${esc(s.email||'-')}</td><td>${(s.products||[]).map(p=>`<span class="pill">${esc(p.name)}</span>`).join(' ')||'<span class="muted">No products assigned</span>'}</td><td class="right">${money(s.balance)}</td><td class="right"><button class="secondary" onclick="manageSupplierProducts(${s.id},'${esc(s.name).replace(/'/g,"&#39;")}')">Products</button></td></tr>`).join('')}</tbody></table></div></div>`}
async function supplierForm(){const ps=await api('/products');$('form').innerHTML=`<div class="inline-form"><input id="sn" placeholder="Supplier name"><input id="sph" placeholder="Phone"><input id="sem" type="email" placeholder="Email"><div class="selection-box"><b>Products this supplier supplies</b><small>Only selected products will be available for this supplier in purchasing/receiving.</small><div class="check-grid">${ps.map(p=>`<label><input type="checkbox" data-supplier-product="${p.id}"> ${esc(p.name)}${p.sku?' - '+esc(p.sku):''}</label>`).join('')||'<span class="muted">Create products first, or save the supplier and assign them later.</span>'}</div></div><button onclick="saveSupplier()">Save supplier</button></div>`}
async function saveSupplier(){const productIds=[...document.querySelectorAll('[data-supplier-product]:checked')].map(x=>Number(x.dataset.supplierProduct));await api('/suppliers',{method:'POST',body:JSON.stringify({name:$('sn').value,phone:$('sph').value,email:$('sem').value,productIds})});suppliers()}
async function manageSupplierProducts(id,name){const [ps,sups]=await Promise.all([api('/products'),api('/suppliers')]),s=sups.find(x=>Number(x.id)===Number(id)),chosen=new Set((s?.products||[]).map(x=>Number(x.id)));$('form').innerHTML=`<div class="relation-editor"><div><h4>${esc(name)} - Products supplied</h4><p class="muted">Purchasing will only show products selected here when this supplier is chosen.</p></div><div class="check-grid">${ps.map(p=>`<label><input type="checkbox" data-edit-supplier-product="${p.id}" ${chosen.has(Number(p.id))?'checked':''}> ${esc(p.name)}${p.sku?' - '+esc(p.sku):''}</label>`).join('')||'<span class="muted">No products registered.</span>'}</div><button onclick="saveSupplierProducts(${id})">Save product list</button></div>`}
async function saveSupplierProducts(id){const productIds=[...document.querySelectorAll('[data-edit-supplier-product]:checked')].map(x=>Number(x.dataset.editSupplierProduct));await api('/suppliers/'+id+'/products',{method:'PUT',body:JSON.stringify({productIds})});suppliers()}
async function people(type,label){const rows=await api('/'+type);$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>${label}s</h3><button onclick="personForm('${type}','${label}')">+ Add ${label}</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th class="right">Balance</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.phone)}</td><td>${esc(x.email)}</td><td class="right">${money(x.balance)}</td></tr>`).join('')}</tbody></table></div></div>`}
function personForm(type,label){$('form').innerHTML=`<div class="inline-form"><input id="n" placeholder="${label} name"><input id="ph" placeholder="Phone"><input id="em" placeholder="Email"><button onclick="savePerson('${type}','${label}')">Save</button></div>`}
async function savePerson(type,label){await api('/'+type,{method:'POST',body:JSON.stringify({name:$('n').value,phone:$('ph').value,email:$('em').value})});people(type,label)}

let poDraft={supplierId:null,branchId:null,items:[]},supplierProductsCache=[];
async function purchasing(){const [o,pos,grns,moves]=await Promise.all([api('/purchasing/overview'),api('/purchase-orders'),api('/grns'),api('/stock-movements')]);let poRows=pos.map(x=>'<tr><td><b>'+esc(x.po_no)+'</b><small>'+esc(x.branch_name||'')+'</small></td><td>'+esc(x.supplier_name)+'</td><td><span class="pill">'+esc(x.status)+'</span></td><td>'+Number(x.received_qty)+'/'+Number(x.total_qty)+'</td><td>'+money(x.total)+'</td><td class="right">'+(x.status==='draft'?'<button class="secondary" onclick="submitPO('+x.id+')">Submit for Approval</button>':'')+(['ordered','partial'].includes(x.status)?' <button onclick="receivePO('+x.id+')">Receive</button>':'')+' <button class="secondary" onclick="openPdf(\'/documents/purchase-order/'+x.id+'/pdf\')">PDF</button>'+'</td></tr>').join('')||'<tr><td colspan="6">No purchase orders yet.</td></tr>';let grnRows=grns.slice(0,12).map(x=>'<tr><td><b>'+esc(x.grn_no)+'</b><small>'+new Date(x.received_at).toLocaleString()+'</small></td><td>'+esc(x.supplier_name)+'</td><td>'+esc(x.po_no)+'</td><td>'+money(x.total)+'</td></tr>').join('')||'<tr><td colspan="4">No GRNs yet.</td></tr>';let moveRows=moves.slice(0,20).map(x=>'<tr><td>'+new Date(x.created_at).toLocaleString()+'</td><td>'+esc(x.product_name)+'</td><td><span class="pill">'+esc(x.movement_type)+'</span></td><td>'+esc(x.reference_no||'-')+'</td><td>+'+Number(x.quantity)+'</td><td>'+Number(x.stock_before)+'</td><td><b>'+Number(x.stock_after)+'</b></td></tr>').join('')||'<tr><td colspan="7">No stock movements yet.</td></tr>';$('view').innerHTML='<div class="kpi-grid purchase-kpis">'+card('Open POs',o.openOrders,'Draft, ordered & partial','blue')+card('Purchase Value',money(o.purchaseValueMonth),'Current month','purple')+card('GRNs Today',o.receiptsToday,'Goods received','green')+card('Low Stock',o.lowStock,'Requires attention',o.lowStock?'red':'')+'</div><div class="panel"><div class="panel-head"><div><h3>Purchasing & Receiving</h3><p class="muted">Create supplier-filtered purchase orders, receive against them, and update stock through GRNs.</p></div><button onclick="newPurchaseOrder()">+ New Purchase Order</button></div><div id="purchaseWork"></div></div><div class="two-col"><div class="panel"><h3>Purchase Orders</h3><div class="table-wrap"><table><thead><tr><th>PO</th><th>Supplier</th><th>Status</th><th>Qty</th><th>Total</th><th></th></tr></thead><tbody>'+poRows+'</tbody></table></div></div><div class="panel"><h3>Recent GRNs</h3><div class="table-wrap"><table><thead><tr><th>GRN</th><th>Supplier</th><th>PO</th><th>Total</th></tr></thead><tbody>'+grnRows+'</tbody></table></div></div></div><div class="panel"><h3>Recent Stock Movements</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Type</th><th>Reference</th><th>Qty</th><th>Before</th><th>After</th></tr></thead><tbody>'+moveRows+'</tbody></table></div></div>';bindPdfLinks()}
async function newPurchaseOrder(){const [sups,branches]=await Promise.all([api('/suppliers'),api('/branches')]);poDraft={supplierId:null,branchId:branches[0]?.id||null,items:[]};$('purchaseWork').innerHTML='<div class="po-builder"><div class="form-row"><label>Supplier<select id="poSupplier" onchange="loadSupplierProducts()"><option value="">Choose supplier</option>'+sups.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('')+'</select></label><label>Branch<select id="poBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label></div><div id="poProducts" class="muted">Choose a supplier to see only products registered for that supplier.</div><div id="poLines"></div><textarea id="poNotes" placeholder="Purchase notes (optional)"></textarea><div class="builder-actions"><button class="secondary" onclick="purchasing()">Cancel</button><button class="secondary" onclick="previewPO()">Preview</button><button onclick="savePO()">Save Draft PO</button></div></div>'}
async function loadSupplierProducts(){const sid=Number($('poSupplier').value);poDraft.supplierId=sid||null;poDraft.items=[];supplierProductsCache=[];renderPOLines();if(!sid){$('poProducts').innerHTML='<span class="muted">Choose a supplier to see products.</span>';return}const d=await api('/suppliers/'+sid+'/products');supplierProductsCache=d.products||[];$('poProducts').innerHTML='<div class="supplier-products"><div><b>'+esc(d.supplier.name)+' products</b><small>Only registered products are available.</small></div><div class="product-grid">'+(supplierProductsCache.map(p=>'<button class="product-tile" data-po-product="'+p.id+'"><b>'+esc(p.name)+'</b><span>'+(p.sku?esc(p.sku):'No SKU')+'</span><small>Current stock '+Number(p.stock)+'</small></button>').join('')||'<div class="empty">No products are registered for this supplier.</div>')+'</div></div>';document.querySelectorAll('[data-po-product]').forEach(btn=>btn.addEventListener('click',()=>addPOItemFromSupplier(Number(btn.dataset.poProduct))))}
function addPOItemFromSupplier(productId){const p=supplierProductsCache.find(x=>Number(x.id)===Number(productId));if(!p)return;addPOItem(Number(p.id),p.name,Number(p.supplier_price??p.cost??0))}
function addPOItem(productId,name,unitCost){const x=poDraft.items.find(i=>i.productId===productId);if(x)x.qty++;else poDraft.items.push({productId,name,qty:1,unitCost:Number(unitCost||0)});renderPOLines()}
function renderPOLines(){if(!$('poLines'))return;if(!poDraft.items.length){$('poLines').innerHTML='<div class="empty">No products added to this purchase order.</div>';return}const rows=poDraft.items.map((x,i)=>'<tr><td><b>'+esc(x.name)+'</b></td><td><input class="mini-input" type="number" min="0.001" step="0.001" value="'+x.qty+'" onchange="poDraft.items['+i+'].qty=Number(this.value);renderPOLines()"></td><td><input class="mini-input" type="number" min="0" value="'+x.unitCost+'" onchange="poDraft.items['+i+'].unitCost=Number(this.value);renderPOLines()"></td><td>'+money(x.qty*x.unitCost)+'</td><td><button class="ghost" onclick="poDraft.items.splice('+i+',1);renderPOLines()">Remove</button></td></tr>').join('');$('poLines').innerHTML='<div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Unit Cost</th><th>Total</th><th></th></tr></thead><tbody>'+rows+'</tbody></table><div class="po-total"><span>Total</span><strong>'+money(poDraft.items.reduce((n,x)=>n+x.qty*x.unitCost,0))+'</strong></div></div>'}
async function previewPO(){if(!poDraft.supplierId)return alert('Choose a supplier');if(!poDraft.items.length)return alert('Add at least one product');const s=(await api('/suppliers')).find(x=>Number(x.id)===Number(poDraft.supplierId));const total=poDraft.items.reduce((n,x)=>n+x.qty*x.unitCost,0);previewDocument('PURCHASE ORDER','Draft',{Supplier:s?.name||'',Branch:$('poBranch').options[$('poBranch').selectedIndex]?.text||'',Notes:$('poNotes').value||'-'},poDraft.items.map(x=>({name:x.name,qty:x.qty,unit:Number(x.unitCost).toLocaleString(),total:Number(x.qty*x.unitCost).toLocaleString()})),total)}
async function savePO(){if(!poDraft.supplierId)return alert('Choose a supplier');if(!poDraft.items.length)return alert('Add at least one product');await api('/purchase-orders',{method:'POST',body:JSON.stringify({supplierId:poDraft.supplierId,branchId:Number($('poBranch').value)||null,notes:$('poNotes').value,items:poDraft.items.map(x=>({productId:x.productId,qty:x.qty,unitCost:x.unitCost}))})});purchasing()}
async function submitPO(id){const comment=prompt('Optional note to the approving supervisor:')||'';await api('/purchase-orders/'+id+'/submit',{method:'POST',body:JSON.stringify({comment})});alert('Purchase order submitted for approval');purchasing()}
async function receivePO(id){const d=await api('/purchase-orders/'+id);const rows=d.items.map(x=>{const out=Number(x.qty_ordered)-Number(x.qty_received);return '<tr><td><b>'+esc(x.product_name)+'</b></td><td>'+Number(x.qty_ordered)+'</td><td>'+Number(x.qty_received)+'</td><td>'+out+'</td><td><input class="mini-input receive-qty" data-item="'+x.id+'" type="number" min="0" max="'+out+'" step="0.001" value="'+out+'"></td><td><input class="mini-input receive-cost" data-item="'+x.id+'" type="number" min="0" value="'+Number(x.unit_cost)+'"></td></tr>'}).join('');$('purchaseWork').innerHTML='<div class="receipt-builder"><div class="panel-head"><div><h3>Receive '+esc(d.order.po_no)+'</h3><p class="muted">'+esc(d.order.supplier_name)+' · Receive only outstanding quantities.</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Ordered</th><th>Received</th><th>Outstanding</th><th>Receive Now</th><th>Unit Cost</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="form-row"><label>Supplier reference<input id="grnSupplierRef" placeholder="Invoice / delivery note"></label><label>Receiving notes<input id="grnNotes" placeholder="Optional notes"></label></div><div class="builder-actions"><button class="secondary" onclick="purchasing()">Cancel</button><button onclick="saveReceipt('+id+')">Post GRN & Update Stock</button></div></div>'}
async function saveReceipt(id){const items=[...document.querySelectorAll('.receive-qty')].map(q=>({itemId:Number(q.dataset.item),qty:Number(q.value),unitCost:Number(document.querySelector('.receive-cost[data-item="'+q.dataset.item+'"]').value)})).filter(x=>x.qty>0);if(!items.length)return alert('Enter at least one received quantity');await api('/purchase-orders/'+id+'/receive',{method:'POST',body:JSON.stringify({items,supplierReference:$('grnSupplierRef').value,notes:$('grnNotes').value})});purchasing()}

async function expenses(){const rows=await api('/expenses');$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Expenses & Cost Register</h3><p class="muted">Manual operating expenses and automatically reconciled costs from system transactions.</p></div><button onclick="expenseForm()">+ Record manual expense</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Category</th><th>Description</th><th>Source</th><th>Treatment</th><th class="right">Amount</th><th></th></tr></thead><tbody>'+rows.map(x=>'<tr><td><b>'+esc(x.reference_no||('EXP-'+x.id))+'</b></td><td>'+esc(x.expense_date).slice(0,10)+'</td><td>'+esc(x.category)+'</td><td>'+esc(x.description)+(x.supplier_name?'<small>'+esc(x.supplier_name)+'</small>':'')+'</td><td>'+(x.auto_generated?'<span class="pill">Auto · '+esc(x.source_type||'System')+'</span>':'<span class="pill">Manual</span>')+'</td><td>'+esc(String(x.accounting_treatment||'operating_expense').replaceAll('_',' '))+'</td><td class="right">'+money(x.amount)+'</td><td class="right"><button class="secondary pdf-link" data-pdf="/documents/expense/'+x.id+'/pdf">PDF</button></td></tr>').join('')+'</tbody></table></div></div>';bindPdfLinks()}
function expenseForm(){$('form').innerHTML='<div class="inline-form"><input id="ec" placeholder="Category"><input id="ed" placeholder="Description"><input id="ea" type="number" min="0" placeholder="Amount"><input id="eDate" type="date"><div class="builder-actions"><button class="secondary" onclick="previewExpense()">Preview</button><button onclick="saveExpense()">Save Expense</button></div></div>'}
function previewExpense(){const amount=Number($('ea').value||0);if(!$('ed').value.trim()||amount<=0)return alert('Enter description and amount');previewDocument('EXPENSE / COST VOUCHER','Draft',{Category:$('ec').value||'General',Date:$('eDate').value||new Date().toISOString().slice(0,10),Source:'Manual'},[{name:$('ed').value,qty:'',unit:'',total:amount.toLocaleString()}],amount)}
async function saveExpense(){await api('/expenses',{method:'POST',body:JSON.stringify({category:$('ec').value,description:$('ed').value,amount:$('ea').value,expenseDate:$('eDate').value||null})});expenses()}
async function orders(){const rows=await api('/sales');$('view').innerHTML=`<div class="panel"><h3>Orders & Receipts</h3><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Cashier</th><th>Payment</th><th>Date</th><th class="right">Total</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.receipt_no)}</b></td><td>${esc(x.customer_name||'Walk-in')}</td><td>${esc(x.cashier)}</td><td>${esc(x.payment_method)}</td><td>${new Date(x.created_at).toLocaleString()}</td><td class="right">${money(x.total)}</td></tr>`).join('')}</tbody></table></div></div>`}
async function pos(){const ps=await api('/products');cart=[];$('view').innerHTML=`<div class="pos-grid"><div class="panel"><h3>New Sale</h3><input id="scan" class="scan" autofocus placeholder="Scan barcode and press Enter"><div class="product-grid">${ps.filter(p=>p.active).map(p=>`<button class="product-tile" onclick="addCart(${p.id},'${esc(p.name).replace(/'/g,"&#39;")}',${Number(p.price)})"><b>${esc(p.name)}</b><span>${money(p.price)}</span><small>Stock ${p.stock}</small></button>`).join('')}</div></div><div class="panel cart"><h3>Current cart</h3><div id="cartRows"></div><div class="cart-total"><span>Total</span><strong id="cartTotal">UGX 0</strong></div><select id="pay"><option value="cash">Cash</option><option value="mobile money">Mobile Money</option><option value="card">Card</option><option value="bank transfer">Bank Transfer</option><option value="credit">Credit</option></select><button class="checkout" onclick="checkout()">Complete Sale</button><div id="receiptWrap"></div></div></div>`;$('scan').addEventListener('keydown',e=>{if(e.key==='Enter'){const p=ps.find(x=>x.barcode===$('scan').value.trim());if(p){addCart(p.id,p.name,Number(p.price));$('scan').value=''}}})}
function addCart(id,name,price){const x=cart.find(i=>i.productId===id);if(x)x.qty++;else cart.push({productId:id,name,price,qty:1});renderCart()}function renderCart(){if(!$('cartRows'))return;$('cartRows').innerHTML=cart.map((x,i)=>`<div class="cart-row"><div><b>${esc(x.name)}</b><small>${money(x.price)} each</small></div><div class="qty"><button onclick="chgQty(${i},-1)">−</button><span>${x.qty}</span><button onclick="chgQty(${i},1)">+</button></div><b>${money(x.price*x.qty)}</b></div>`).join('')||'<div class="empty">No items yet</div>';$('cartTotal').textContent=money(cart.reduce((s,x)=>s+x.price*x.qty,0))}function chgQty(i,n){cart[i].qty+=n;if(cart[i].qty<=0)cart.splice(i,1);renderCart()}
async function checkout(){if(!cart.length)return alert('Cart is empty');const j=await api('/sales',{method:'POST',body:JSON.stringify({items:cart.map(x=>({productId:x.productId,qty:x.qty})),paymentMethod:$('pay').value})});$('receiptWrap').innerHTML=`<div class="receipt"><h3>OWLTECH POS</h3><div>Receipt: ${j.sale.receipt_no}</div><hr>${cart.map(x=>`<div>${esc(x.name)} x ${x.qty}<span>${money(x.price*x.qty)}</span></div>`).join('')}<hr><h3>Total ${money(j.sale.total)}</h3><div>Payment: ${esc(j.sale.payment_method)}</div><button onclick="window.print()">Print 80mm Receipt</button></div>`;cart=[];renderCart()}
(async()=>{if(token){try{user=await api('/me');showApp()}catch{localStorage.removeItem('pos_token')}}})();